using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.IO;
using System.Drawing;

namespace SewingProduction.Core.Class.Settings
{
    public class AppSettings
    {
        public string Theme { get; set; } = "Gray";
        public int FontSize { get; set; } = 10;
        public bool SaveOpenTabs { get; set; } = true;
        public Dictionary<string, UserSettings> Users { get; set; } = new();
    }

    public class UserSettings
    {
        public List<string> OpenTabs { get; set; } = new();
        public List<string> Logins { get; set; } = new();
        public string SavedPassword { get; set; } = "";
    }

    public static class SettingsManager
    {
        private static readonly string SettingsPath = "settings.json";
        private static AppSettings _settings;

        public static AppSettings Current => _settings ??= Load();

        public static void Save()
        {
            var json = JsonConvert.SerializeObject(_settings, Formatting.Indented);
            File.WriteAllText(SettingsPath, json);
        }
        #region Тема
        public static void LoadTheme()
        {
            if (!string.IsNullOrEmpty(Current.Theme))
                ThemeManager.SetTheme(Current.Theme);
        }

        public static void SetTheme(string theme)
        {
            Current.Theme = theme;
            Save();
        }

        #endregion
        #region Логин
        public static List<string> GetLoginHistory()
        {
            return Current.Users.TryGetValue("logins", out var user) ? user.Logins : new List<string>();
        }

        public static void AddLogin(string login)
        {
            if (!Current.Users.ContainsKey("logins"))
                Current.Users["logins"] = new UserSettings();

            var logins = Current.Users["logins"].Logins;
            logins.RemoveAll(l => l.Equals(login, StringComparison.OrdinalIgnoreCase));
            logins.Add(login);

            Save();
        }
        #endregion
        #region Пароль
        public static void SavePassword(string login, string password)
        {
            if (string.IsNullOrWhiteSpace(login)) return;

            if (!Current.Users.ContainsKey(login))
                Current.Users[login] = new UserSettings();

            Current.Users[login].SavedPassword = password;
            Save();
        }
        public static string GetSavedPassword(string login)
        {
            if (string.IsNullOrWhiteSpace(login)) return "";

            return Current.Users.TryGetValue(login, out var settings)
                ? settings.SavedPassword ?? ""
                : "";
        }
        public static void ClearSavedPassword(string login)
        {
            if (string.IsNullOrWhiteSpace(login)) return;

            if (Current.Users.ContainsKey(login))
            {
                Current.Users[login].SavedPassword = "";
                Save();
            }
        }
        #endregion
        #region Вкладки
        public static List<string> GetOpenTabs(string username)
        {
            return Current.Users.TryGetValue(username, out var user) ? user.OpenTabs : new List<string>();
        }

        public static void SetOpenTabs(string username, List<string> tabs)
        {
            if (string.IsNullOrWhiteSpace(username))
                return;

            if (!Current.Users.ContainsKey(username))
                Current.Users[username] = new UserSettings();

            Current.Users[username].OpenTabs = tabs;
            Save();
        }
        public static bool GetSaveOpenTabs()
        {
            return Current.SaveOpenTabs;
        }

        public static void SetSaveOpenTabs(bool value)
        {
            Current.SaveOpenTabs = value;
            Save();
        }
        #endregion

        private static AppSettings Load()
        {
            if (File.Exists(SettingsPath))
            {
                try
                {
                    var json = File.ReadAllText(SettingsPath);
                    return JsonConvert.DeserializeObject<AppSettings>(json) ?? new AppSettings();
                }
                catch
                {
                    return new AppSettings();
                }
            }
            return new AppSettings();
        }
        public static void SetFontSize(int size)
        {
            Current.FontSize = size;
            ThemeManager.UpdateDefaultFont(new Font("Arial", size));
            Save();
        }
        public static void ClearLoginAndPasswordHistory()
        {
            if (Current.Users.ContainsKey("logins"))
            {
                Current.Users.Remove("logins");
            }

            foreach (var user in Current.Users.Values)
            {
                user.SavedPassword = "";
            }

            Save();
        }
    }
}
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using SewingProduction.Features.UserDistribution.Helpers;
using System.Windows.Forms;

namespace SewingProduction.Core.Class.Settings
{
    public class FormManager
    {
        private readonly Form _mainForm;
        private readonly MenuStrip _menuStrip;
        private readonly UserClass _user;
        private readonly Dictionary<string, Form> _openedForms;

        public FormManager(Form mainForm, MenuStrip menuStrip, UserClass user)
        {
            _mainForm = mainForm;
            _menuStrip = menuStrip;
            _user = user;
            _openedForms = new Dictionary<string, Form>();
        }

        public void OpenForm(Form form, object sender = null)
        {
            form.MdiParent = _mainForm;
            string menuItemName = sender switch
            {
                ToolStripMenuItem menuItem => menuItem.Name,
                string name => name,
                _ => null
            };

            if (!string.IsNullOrEmpty(menuItemName))
            {
                if (_openedForms.TryGetValue(menuItemName, out Form existingForm))
                {
                    if (existingForm != null && !existingForm.IsDisposed)
                    {
                        existingForm.Activate();
                        return;
                    }
                    else
                        _openedForms.Remove(menuItemName);
                }
                _openedForms.Add(menuItemName, form);
            }

            form.FormClosed += (s, e) =>
            {
                var closedForm = s as Form;
                var item = _openedForms.FirstOrDefault(x => x.Value == closedForm);
                if (!string.IsNullOrEmpty(item.Key))
                {
                    _openedForms.Remove(item.Key);
                }
            };

            form.Show();
        }

        public async Task RestoreOpenTabs()
        {
            var openTabs = SettingsManager.GetOpenTabs(_user.UserName);
            foreach (var menuItemName in openTabs)
            {
                ToolStripMenuItem menuItem = FindMenuItemByName(_menuStrip.Items, menuItemName);
                if (menuItem != null)
                {
                    await Task.Delay(100);
                    menuItem.PerformClick();
                }
            }
        }

        public void SaveOpenTabs()
        {
            SettingsManager.SetOpenTabs(_user.UserName, _openedForms.Keys.ToList());
        }
        public ToolStripMenuItem GetMenuItemByName(string name)
        {
            return FindMenuItemByName(_menuStrip.Items, name);
        }
        private ToolStripMenuItem FindMenuItemByName(ToolStripItemCollection items, string name)
        {
            foreach (ToolStripItem item in items)
            {
                if (item.Name == name && item is ToolStripMenuItem menuItem)
                    return menuItem;

                if (item is ToolStripMenuItem parentMenu && parentMenu.DropDownItems.Count > 0)
                {
                    var found = FindMenuItemByName(parentMenu.DropDownItems, name);
                    if (found != null)
                        return found;
                }
            }
            return null;
        }


    }
}
