            view.EndUpdate();
        }

        /// <summary>
        /// Загружает изображение в `PictureBox` по `annId`
        /// </summary>
        /// <param name="pictureBox">PictureBox для загрузки изображения</param>
        /// <param name="data">DataTable с путем к изображению</param>
        public static void LoadImage(PictureBox pictureBox, DataTable data)
        {
            if (data != null && data.Rows.Count > 0)
            {
                pictureBox.ImageLocation = data.Rows[0]["pathpict"].ToString();
            }
        }

        /// <summary>
        /// Возвращает имя выбранного столбца для поиска
        /// </summary>
        /// <param name="kode">Радиокнопка "Код"</param>
        /// <param name="articul">Радиокнопка "Артикул"</param>
        /// <param name="model">Радиокнопка "Модель"</param>
        /// <param name="group">Радиокнопка "Группа"</param>
        /// <returns>Имя столбца для поиска</returns>
        public static string GetSelectedColumnName(bool kode, bool articul, bool model, bool group)
        {
            if (kode) return "kod";
            if (articul) return "articul";
            if (model) return "mod";
            if (group) return "grup";
            return string.Empty;
        }
        /// <summary>
        /// Проверяет, загружены ли данные в GridView
        /// </summary>
        /// <param name="view">GridView для проверки</param>
        /// <returns>True, если данные загружены</returns>
        public static bool IsDataTableLoaded(GridView view)
        {
            return view.DataSource is BindingSource bindingSource &&
                   bindingSource.DataSource is DataTable dataTable &&
                   dataTable.Rows.Count > 0;
        }

        /// <summary>
        /// Снимает выделение всех строк, кроме текущей
        /// </summary>
        /// <typeparam name="T">Тип данных (например, MyDataANN)</typeparam>
        /// <param name="gridView">GridView, в котором выполняется выделение</param>
        /// <param name="rowHandle">Индекс выбранной строки</param>
        public static void UpdateExclusiveCheck<T>(GridView gridView, int rowHandle) where T : class
        {
            var selectedData = gridView.GetRow(rowHandle) as T;
            if (selectedData is ICheckable checkableSelectedData)
            {
                checkableSelectedData.IsChecked = true;

                // Снимаем выделение с остальных строк
                for (int i = 0; i < gridView.RowCount; i++)
                {
                    if (i != rowHandle)
                    {
                        var otherData = gridView.GetRow(i) as T;
                        if (otherData is ICheckable checkableOtherData && checkableOtherData.IsChecked)
                        {
                            checkableOtherData.IsChecked = false;
                        }
                    }
                }
            }
            gridView.RefreshData();
        }
        #endregion
    }
}


using System;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace SewingProduction
{
    /// <summary>
    /// Вспомогательный класс для работы со сплеш-скрином при загрузке данных
    /// </summary>
    public static class SplashScreenHelper
    {
        private static SplashScreen _splashScreen;
        private static Thread _splashThread;

        /// <summary>
        /// Показывает сплеш-скрин в отдельном потоке
        /// </summary>
        public static void ShowSplash()
        {
            // Создаем и запускаем сплеш-скрин в отдельном потоке
            _splashThread = new Thread(() =>
            {
                _splashScreen = new SplashScreen();
                _splashScreen.FormClosed += (s, e) => Application.ExitThread();
                _splashScreen.StartPosition = FormStartPosition.CenterScreen;
                _splashScreen.TopMost = true;
                Application.Run(_splashScreen);
            });

            _splashThread.SetApartmentState(ApartmentState.STA);
            _splashThread.Start();
        }

        /// <summary>
        /// Скрывает сплеш-скрин
        /// </summary>
        public static void CloseSplash()
        {
            if (_splashScreen != null && !_splashScreen.IsDisposed)
            {
                if (_splashScreen.InvokeRequired)
                {
                    _splashScreen.Invoke(new Action(() => _splashScreen.Close()));
                }
                else
                {
                    _splashScreen.Close();
                }

                if (_splashThread != null && _splashThread.IsAlive)
                {
                    _splashThread.Join(1000);
                }
            }
        }

        /// <summary>
        /// Запускает операцию с отображением сплеш-скрина
        /// </summary>
        /// <param name="action">Действие, которое нужно выполнить</param>
        public static async Task RunWithSplashAsync(Func<Task> action)
        {
            ShowSplash();
            try
            {
                await action();
            }
            finally
            {
                CloseSplash();
            }
        }
    }
}
using System;
using System.IO;
using System.Xml;
using DevExpress.XtraEditors;
using SewingProduction.Interfaces;

namespace SewingProduction.Helpers
{
    public class SplitContainerHelper
    {
        private readonly FileLogger _logger = new FileLogger();

        public void SaveSplitContainerSettings(SplitContainerControl splitContainer, string fileName)
        {
            try
            {
                string appPath = System.Windows.Forms.Application.StartupPath;
                string settingsPath = Path.Combine(appPath, "Settings");

                // Create directory if it doesn't exist
                if (!Directory.Exists(settingsPath))
                    Directory.CreateDirectory(settingsPath);

                string fullPath = Path.Combine(settingsPath, fileName);

                // Create XML document with splitter position
                using (XmlWriter writer = XmlWriter.Create(fullPath))
                {
                    writer.WriteStartDocument();
                    writer.WriteStartElement("SplitContainerLayout");
                    
                    writer.WriteStartElement("Splitter");
                    writer.WriteAttributeString("Position", splitContainer.SplitterPosition.ToString());
                    writer.WriteEndElement(); // Splitter
                    
                    writer.WriteEndElement(); // SplitContainerLayout
                    writer.WriteEndDocument();
                }
            }
            catch (Exception ex)
            {
                _logger.LogErrorAsync(ex, "Error saving split container settings");
            }
        }

        public void LoadSplitContainerSettings(SplitContainerControl splitContainer, string fileName)
        {
            try
            {
                string appPath = System.Windows.Forms.Application.StartupPath;
                string settingsPath = Path.Combine(appPath, "Settings");
                string fullPath = Path.Combine(settingsPath, fileName);

                if (!File.Exists(fullPath))
                    return;

                using (XmlReader reader = XmlReader.Create(fullPath))
                {
                    while (reader.Read())
                    {
                        if (reader.NodeType == XmlNodeType.Element && reader.Name == "Splitter")
                        {
                            string positionStr = reader.GetAttribute("Position");
                            if (int.TryParse(positionStr, out int position))
                            {
                                splitContainer.SplitterPosition = position;
                            }
                            break;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogErrorAsync(ex, "Error loading split container settings");
            }
        }
    }
} 
