    public static class ControlExtensions
    {
        public static Task InvokeAsync(this Control control, Func<Task> asyncAction)
        {
            var tcs = new TaskCompletionSource<bool>();
            control.BeginInvoke(new MethodInvoker(async () =>
            {
                try
                {
                    await asyncAction();
                    tcs.SetResult(true);
                }
                catch (Exception ex)
                {
                    tcs.SetException(ex);
                }
            }));
            return tcs.Task;
        }
    }
