        /// <summary>
        /// РћР±СЂР°Р±РѕС‚С‡РёРє РЅР°Р¶Р°С‚РёСЏ РЅР° РєРЅРѕРїРєСѓ "Р’СЃС‚Р°РІРёС‚СЊ РёР· Р±СѓС„РµСЂР°"
        /// </summary>
        private async void buffer_Click(object sender, EventArgs e)
        {
            if (_bufferWorkDivision > 0)
            {
                try
                {
                    var result = MessageBox.Show(
     "РћС‡РёСЃС‚РёС‚СЊ С‚РµРєСѓС‰РёРµ РґР°РЅРЅС‹Рµ РїРµСЂРµРґ РІСЃС‚Р°РІРєРѕР№ РёР· Р±СѓС„РµСЂР°?",
     "Р’СЃС‚Р°РІРєР° РёР· Р±СѓС„РµСЂР°",
     MessageBoxButtons.YesNo,
     MessageBoxIcon.Question);

                    if (result == DialogResult.Yes)
                    {
                        if (_normRaszList == null || _normRaskList == null || _normKontList == null)
                        {
                            await InitializeBindingsAsync();
                        }

                        // РћС‡РёС‰Р°РµРј С‚РµРєСѓС‰РёРµ СЃРїРёСЃРєРё
                        _normRaszList?.Clear();
                        _normRaskList?.Clear();
                        _normKontList?.Clear();

                        _normRaszBindingSource?.ResetBindings(false);
                        _normRaskBindingSource?.ResetBindings(false);
                        _normKontBindingSource?.ResetBindings(false);
                    }

                    // Р—Р°РіСЂСѓР¶Р°РµРј РґР°РЅРЅС‹Рµ РёР· Р±СѓС„РµСЂР°
                    //await WorkDivisionLoadAsync(caller: "buffer", _bufferWorkDivision);
                    //MessageBox.Show("Р”Р°РЅРЅС‹Рµ РёР· Р±СѓС„РµСЂР° СѓСЃРїРµС€РЅРѕ Р·Р°РіСЂСѓР¶РµРЅС‹", "РРЅС„РѕСЂРјР°С†РёСЏ",
