using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using DevExpress.XtraBars.Ribbon;
using SewingProduction.Helpers;

namespace SewingProduction.Features.UserDistribution.Helpers
{
    public static class ActionLogger
    {
        private static readonly DatabaseHelper dbHelper = new DatabaseHelper("ace");

        public static async Task Log(int userId, string eventDescription, string komp = null, string NameForm = null, string NameObject = null)
        {
            komp = Environment.MachineName;

            string query = @"
                INSERT INTO ActionHistory 
                (UserID, NameObject, NameForm, Event, EventDate, Komp)
                VALUES (@UserID, @NameObject, @NameForm, @Event, @EventDate, @Komp)";

            await dbHelper.ExecuteQueryAsync(query, new Dictionary<string, object>
            {
                ["@UserID"] = userId,
                ["@NameObject"] = NameObject ?? (object)DBNull.Value,
                ["@NameForm"] = NameForm ?? (object)DBNull.Value,
                ["@Event"] = eventDescription,
                ["@EventDate"] = DateTime.Now,
                ["@Komp"] = komp
            });
        }

    }
}
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows.Forms;
using SewingProduction.form.UserDistribution;

namespace SewingProduction.Features.UserDistribution.Helpers
{
    public class FormScanner
    {
        private readonly AdminFormDataService _adminFormDataService;
        private readonly UserClass _user;

        public FormScanner(AdminFormDataService dataService, UserClass user)
        {
            _adminFormDataService = dataService;
            _user = user;
        }

        public async Task ScanAndSave(string formClassName, int formId, DataTable existingObjects)
        {
            Type formType = FindFormTypeByName(formClassName);
            if (formType == null)
            {
                MessageBox.Show($"Форма '{formClassName}' не найдена.");
                return;
            }

            Form formInstance = CreateFormInstance(formType);
            if (formInstance == null)
            {
                MessageBox.Show($"Форма '{formClassName}' не содержит подходящего конструктора (UserClass или без параметров).");
                return;
            }

            // ❗ НЕ ВЫЗЫВАЕМ Show или Load
            // Просто сканируем контролы
            var controls = GetAllControls(formInstance);

            foreach (var ctrl in controls)
            {
                string objectName = ctrl.Name;
                if (string.IsNullOrWhiteSpace(objectName)) continue;

                string objectType = ctrl.GetType().Name;
                string baseText = string.IsNullOrWhiteSpace(ctrl.Text) ? "" : ctrl.Text.Trim();
                string objectNameRus = GetRussianNameForObject(baseText, objectType);

                bool alreadyExists = existingObjects.AsEnumerable()
                    .Any(row => row["ObjectName"].ToString() == objectName);

                if (!alreadyExists)
                {
                    await _adminFormDataService.InsertObjectForm(
                        objectName,
                        objectNameRus,
                        objectType,
                        _user.UserId,
                        formId
                    );
                }
            }

            MessageBox.Show($"Сканирование формы '{formClassName}' завершено.");
        }
        private string GetRussianNameForObject(string baseText, string objectType)
        {
            string prefix;

            switch (objectType)
            {
                case "CustomButton": case "Button":
                    prefix = "Кнопка";
                    break;
                case "CustomLabel": case "Label":
                    prefix = "Метка";
                    break;
                case "CustomTextBox": case "TextBox": 
                case "CustomMaskedTextBox": case "MaskedTextBox":
                    prefix = "Поле";
                    break;
                case "CustomComboBox": case "ComboBox":
                    prefix = "Раскрывающийся список";
                    break;
                case "CustomCheckBox": case "CheckBox":
                    prefix = "Галочка";
                    break;
                case "CustomGridControl": case "GridControl":
                    prefix = "Таблица";
                    break;
                case "CustomGroupBox":  case "GroupBox":
                    prefix = "Группа";
                    break;
                case "CustomToolStripMenuItem":  case "ToolStripMenuItem":
                    prefix = "Элемент меню";
                    break;
                default:
                    prefix = "Объект";
                    break;
            }

            if (string.IsNullOrWhiteSpace(baseText))
            {
                return prefix;
            }
            else
            {
                return prefix + " \"" + baseText + "\"";
            }
        }

        public Form CreateFormInstance(Type formType)
        {
            try
            {
                // Пытаемся найти пустой конструктор
                ConstructorInfo defaultCtor = formType.GetConstructor(Type.EmptyTypes);
                if (defaultCtor != null)
                {
                    return (Form)defaultCtor.Invoke(null);
                }
                // Пытаемся найти конструктор с UserClass
                ConstructorInfo ctorWithUser = formType.GetConstructor(new[] { typeof(UserClass) });
                if (ctorWithUser != null)
                {
                    return (Form)ctorWithUser.Invoke(new object[] { _user });
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Ошибка создания формы: {ex.Message}");
            }

            return null;
        }

        private Type FindFormTypeByName(string formClassName)
        {
            foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
            {
                Type[] types;
                try
                {
                    types = assembly.GetTypes();
                }
                catch (ReflectionTypeLoadException ex)
                {
                    types = ex.Types.Where(t => t != null).ToArray(); // пропускаем битые типы
                }

                foreach (var type in types)
                {
                    if (type.IsSubclassOf(typeof(Form)) && type.Name == formClassName)
                        return type;
                }
            }

            return null;
        }

        private List<Control> GetAllControls(Control root)
        {
            List<Control> controls = new List<Control>();
            foreach (Control ctrl in root.Controls)
            {
                controls.Add(ctrl);
                if (ctrl.HasChildren)
                    controls.AddRange(GetAllControls(ctrl));
            }
            return controls;
        }
        #region load form
        public List<string> GetAllFormNamesInProject()
        {
            return AppDomain.CurrentDomain.GetAssemblies()
                .Where(a => !a.IsDynamic)
                .SelectMany(a =>
                {
                    try { return a.GetTypes(); }
                    catch (ReflectionTypeLoadException ex)
                    {
                        return ex.Types.Where(t => t != null);
                    }
                })
                .Where(t =>
                    typeof(CustomForm).IsAssignableFrom(t) &&
                    t.IsClass &&
                    !t.IsAbstract)
                .Select(t => t.Name)
                .Distinct()
                .ToList();
        }
        public async Task<DataTable> CheckMissingFormsAsyncAndAdd(DataTable dbForms)
        {
            var knownFormNames = GetAllFormNamesInProject();

            // Добавляем колонки если их нет
            if (!dbForms.Columns.Contains("Missing"))
                dbForms.Columns.Add("Missing", typeof(bool));
            if (!dbForms.Columns.Contains("Added"))
                dbForms.Columns.Add("Added", typeof(bool));

            var dbFormNames = dbForms.AsEnumerable()
                .Select(r => r["NameForm"].ToString())
                .ToHashSet();

            // Отметка тех, кто в БД, но не в проекте
            foreach (DataRow row in dbForms.Rows)
            {
                string nameForm = row["NameForm"]?.ToString();
                if (!knownFormNames.Contains(nameForm))
                {
                    row["Missing"] = true;
                    row["Added"] = false;
                    row["NameFormRus"] = (row["NameFormRus"]?.ToString() ?? "") + " ⚠ отсутствует";
                }
                else
                {
                    row["Missing"] = false;
                    row["Added"] = false;
                }
            }

            // Те, кто есть в проекте, но не в БД
            foreach (string name in knownFormNames)
            {
                if (!dbFormNames.Contains(name))
                {
                    // Добавляем в БД
                    int newId = await _adminFormDataService.InsertProjectForms(name, name, _user.UserId);

                    // И в DataTable
                    var newRow = dbForms.NewRow();
                    newRow["ProjectFormsID"] = newId;
                    newRow["NameForm"] = name;
                    newRow["NameFormRus"] = "✅ добавлено из проекта";
                    newRow["UserName"] = _user.UserName;
                    newRow["Missing"] = false;
                    newRow["Added"] = true;
                    dbForms.Rows.Add(newRow);
                }
            }

            return dbForms;
        }
        #endregion
        #region load object
        public async Task<DataTable> CheckMissingObjectsAsyncAndAdd(string formClassName, int formId, DataTable dbObjects)
        {
            Type formType = FindFormTypeByName(formClassName);
            if (formType == null)
            {
                MessageBox.Show($"Форма '{formClassName}' не найдена.");
                return dbObjects;
            }

            Form formInstance = CreateFormInstance(formType);
            if (formInstance == null)
            {
                MessageBox.Show($"Форма '{formClassName}' не создана.");
                return dbObjects;
            }

            if (!dbObjects.Columns.Contains("MissingObj"))
                dbObjects.Columns.Add("MissingObj", typeof(bool));
            if (!dbObjects.Columns.Contains("AddedObj"))
                dbObjects.Columns.Add("AddedObj", typeof(bool));

            var knownControls = new List<Control>();

            // Добавляем саму форму как контрол
            if (!string.IsNullOrWhiteSpace(formInstance.Name))
                knownControls.Add(formInstance);

            // Добавляем все вложенные контролы
            knownControls.AddRange(GetAllControls(formInstance)
                .Where(c => !string.IsNullOrWhiteSpace(c.Name)));

            var dbObjectNames = dbObjects.AsEnumerable()
                .Select(r => r["ObjectName"].ToString())
                .ToHashSet();

            // Отметка тех, кто в БД, но не в форме
            foreach (DataRow row in dbObjects.Rows)
            {
                string objectName = row["ObjectName"]?.ToString();
                bool found = knownControls.Any(c => c.Name == objectName);
                row["MissingObj"] = !found;
                row["AddedObj"] = false;

                if (!found)
                {
                    row["ObjectNameRus"] = (row["ObjectNameRus"]?.ToString() ?? "") + " ⚠ отсутствует";
                }
            }

            // Добавление тех, кто есть на форме, но не в БД
            foreach (var ctrl in knownControls)
            {
                if (!dbObjectNames.Contains(ctrl.Name))
                {
                    string objectType = ctrl.GetType().Name;
                    string baseText = string.IsNullOrWhiteSpace(ctrl.Text) ? "" : ctrl.Text.Trim();
                    string objectNameRus = GetRussianNameForObject(baseText, objectType);

                    int newId = await _adminFormDataService.InsertObjectForm(
                        ctrl.Name,
                        objectNameRus,
                        objectType,
                        _user.UserId,
                        formId
                    );

                    var newRow = dbObjects.NewRow();
                    newRow["ObjectID"] = newId;
                    newRow["ObjectName"] = ctrl.Name;
                    newRow["ObjectNameRus"] = "✅ добавлено из формы";
                    newRow["ObjectType"] = objectType;
                    newRow["UserName"] = _user.UserName;
                    newRow["MissingObj"] = false;
                    newRow["AddedObj"] = true;
                    dbObjects.Rows.Add(newRow);
                }
            }

            return dbObjects;
        }

        #endregion
    }
}
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows.Forms;
using SewingProduction.form.UserDistribution;

namespace SewingProduction.Features.UserDistribution.Helpers
{
    public class MenuScanner
    {
        private readonly AdminFormDataService _adminFormDataService;
        private readonly UserClass _user;

        public MenuScanner(AdminFormDataService adminFormDataService, UserClass user)
        {
            _adminFormDataService = adminFormDataService;
            _user = user;
        }

        public async Task ScanAndInsertMenuAsync(MenuStrip menuStrip, int formId)
        {
            foreach (ToolStripMenuItem item in menuStrip.Items)
            {
                await ScanMenuItemAsync(item, formId);
            }
        }

        private async Task ScanMenuItemAsync(ToolStripMenuItem item, int formId)
        {
            string name = item.Name;
            string text = item.Text;

            if (!string.IsNullOrEmpty(name))
            {
                bool exists = await _adminFormDataService.ObjectExists(formId, name);

                if (!exists)
                {
                    await _adminFormDataService.InsertObjectForm(name, text, "ToolStripMenuItem", _user.UserId, formId);
                    Debug.WriteLine($"[MenuScanner] ✅ Добавлен: Name = {name}, Text = {text}");
                }
                else
                {
                    Debug.WriteLine($"[MenuScanner] ⚠️ Уже существует: Name = {name}, Text = {text}");
                }
            }

            foreach (ToolStripItem subItem in item.DropDownItems)
            {
                if (subItem is ToolStripMenuItem subMenuItem)
                {
                    await ScanMenuItemAsync(subMenuItem, formId);
                }
            }
        }
        public void ApplyPermissionsToMenu(MenuStrip menuStrip)
        {
            ApplyPermissionsToMenuItems(menuStrip.Items);
        }

        private void ApplyPermissionsToMenuItems(ToolStripItemCollection items, int indentLevel = 0)
        {
            foreach (ToolStripItem item in items)
            {
                if (string.IsNullOrWhiteSpace(item.Name)) continue;

                string objectName = item.Tag as string ?? item.Name;

                bool hasWrite = _user.HasPermission(objectName, "Редактор");
                bool hasRead = _user.HasPermission(objectName, "Просмотр");

                item.Visible = hasRead || hasWrite;
                item.Enabled = hasWrite;

                if (item is ToolStripMenuItem menuItem && menuItem.HasDropDownItems)
                {
                    ApplyPermissionsToMenuItems(menuItem.DropDownItems, indentLevel + 1);
                }
            }
        }
    }

}
using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using DevExpress.XtraBars.Ribbon;
using SewingProduction.Helpers;

namespace SewingProduction.Features.UserDistribution.Helpers
{
    public class UserClass
    {
        private readonly UserClassDataService _userClassDataService;
        DatabaseHelper dbHelper = new DatabaseHelper("ace");
        public int UserId { get; set; }
        public string UserName { get; set; } = string.Empty;
        public int CreatorID { get; set; }
        public int FioID { get; set; }
        public string Fio { get; set; }
        public int BrigID { get; set; }
        public string Brig { get; set; }
        public string Password { get; set; } = "0";
        public List<string> Roles { get; set; } = new List<string>();
        public List<UserClass> Children { get; set; } = new List<UserClass>();
        public DataTable myObjectForm;
        public UserClass()
        { 
            _userClassDataService = new UserClassDataService(dbHelper);
        }
        public async Task LoadUserData()
        {
            DataTable UserData = await _userClassDataService.GetUserData(UserId);

            DataRow rowUserData = UserData.Rows[0];
            UserName = rowUserData["Username"]?.ToString() ?? "";
            CreatorID = rowUserData["CreatorID"] == null ? 0 : (int)rowUserData["CreatorID"];
            FioID = rowUserData["FioID"] == DBNull.Value ? 0 : Convert.ToInt32(rowUserData["FioID"]);
            BrigID = rowUserData["BrigID"] == DBNull.Value ? 0 : Convert.ToInt32(rowUserData["BrigID"]);

            Roles = await _userClassDataService.GetUserRoles(UserId);
        }
        public async Task LoadObjectForm(string NameForm)
        {
            myObjectForm = await _userClassDataService.GetObjectForm(UserId, NameForm);
            int U111 = 0;
        }
        public bool HasPermission(string objectName, string permissionType)
        {
            if (myObjectForm == null || myObjectForm.Rows.Count == 0)
            {
                // Если DataTable пустой, считаем, что прав нет
                return false;
            }
            // Ищем строку, где ObjectName соответствует имени объекта и соответствует нужному разрешению
            foreach (DataRow row in myObjectForm.Rows)
            {
                string objectNameFromTable = row["ObjectName"]?.ToString();
                string modeIdFromTable = row["ModeName"]?.ToString();
                if (objectNameFromTable == objectName && modeIdFromTable == permissionType)
                {
                    return true; // Нашли разрешение
                }
            }
            return false; // Разрешение не найдено
        }
        public async void ExitUser()
        {
            UserId = 0;
            UserName = null;
            CreatorID = 0;
            FioID = 0;
            Roles.Clear();
            myObjectForm?.Clear();
        }
    }
    public class UserClassDataService
    {
        private readonly DatabaseHelper _dbHelper;
        public UserClassDataService(DatabaseHelper dbHelper)
        {
            _dbHelper = dbHelper;
        }

        public async Task<DataTable> GetUserData(int UserId)
        {
            string query = "SELECT * FROM Users WHERE UserId = @UserId";
            return await _dbHelper.ExecuteQueryAsync(query, new Dictionary<string, object> { { "@UserId", UserId } });
        }
        public async Task<List<string>> GetUserRoles(int UserId)
        {
            string query = @"
                SELECT r.RoleName
                FROM Users u
                INNER JOIN UserRoles ur ON u.UserId = ur.UserId
                INNER JOIN Roles r ON ur.RoleId = r.RoleId
                WHERE u.UserId = @UserId";

            DataTable result = await _dbHelper.ExecuteQueryAsync(query, new Dictionary<string, object> { { "@UserId", UserId } });

            List<string> roles = new List<string>();
            foreach (DataRow row in result.Rows)
            {
                roles.Add(row["RoleName"].ToString());
            }
            return roles;
        }
        public async Task<DataTable> GetObjectForm(int UserId, string NameForm)
        {
            string query = $@"
                SELECT o.ObjectName, m.ModeName
                    FROM Users u
                    LEFT JOIN UserRoles ur ON u.UserID = ur.UserID
                    LEFT JOIN Roles r ON ur.RoleID = r.RoleID
                    LEFT JOIN RoleObject ro ON r.RoleID = ro.RoleID
                    LEFT JOIN ObjectForm o ON ro.ObjectID = o.ObjectID
                    LEFT JOIN ProjectForms pf ON o.FormID = pf.ProjectFormsID
                    LEFT JOIN Mode m ON m.ModeID = ro.ModeID
                WHERE u.UserId = @UserId
                AND pf.NameForm = @NameForm";
            return await _dbHelper.ExecuteQueryAsync(query, new Dictionary<string, object> { { "@UserId", UserId } , { "@NameForm", NameForm } });
        }
    }

}
